// PROSM Time's brand for the server-side PDFs (owner 2026-11-09: the documents belong to the
// customer - their logo leads; PROSM Time's full logo, with "WORK, TRACKED.", stays small, and the
// footer says the document was issued through PROSM Time beside the small mark). Built from
// src/assets/brand/prosm-time-logo-pdf.png and prosm-time-mark-pdf.png; kept inline so a PDF never
// depends on fetching an image.
const decode = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const PROSM_FULL_LOGO_PNG = decode("");
export const PROSM_MARK_PNG = decode("");
